<div class="page-heading"><div><div class="eyebrow">YOUTH REGISTRATION</div><h1><?= e($title) ?></h1><p><?= $page === 'edit' ? 'Keep this youth’s information accurate and up to date.' : 'A few details to connect a young person with your community.' ?></p></div><a class="button secondary" href="<?= e(url(isset($person) ? 'profile' : 'records', isset($person) ? ['id' => $person['id']] : [])) ?>">Cancel</a></div>
<?php if ($errors): ?><div class="alert" role="alert"><strong>Please check the following:</strong><?php foreach ($errors as $item): ?><p><?= e($item) ?></p><?php endforeach; ?></div><?php endif; ?>
<form method="post" enctype="multipart/form-data" class="registration-form"><?= csrf() ?><input type="hidden" name="MAX_FILE_SIZE" value="2097152"><div class="form-main"><section class="panel form-section"><div class="section-title"><span>01</span><div><h2>Personal information</h2><p>Fields marked with * are required.</p></div></div><div class="form-grid"><label class="span-two">Full name *<input name="full_name" required maxlength="150" value="<?= e($data['full_name']) ?>" autocomplete="name"></label><label>Birthdate *<input type="date" name="birthdate" id="birthdate" required min="1900-01-01" max="<?= date('Y-m-d') ?>" value="<?= e($data['birthdate']) ?>"></label><label>Age<input id="calculated-age" value="<?= validDate($data['birthdate']) ? age($data['birthdate']) . ' years old' : '' ?>" readonly tabindex="-1"></label><label>Sex *<select name="sex" required><option value="">Select sex</option><?php foreach (['Male', 'Female'] as $option): ?><option <?= $data['sex'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label>Contact number<input type="tel" name="contact_number" maxlength="30" value="<?= e($data['contact_number']) ?>" autocomplete="tel"></label><label class="span-two">Complete address *<textarea name="address" required maxlength="250" rows="2"><?= e($data['address']) ?></textarea></label></div></section>
<section class="panel form-section"><div class="section-title"><span>02</span><div><h2>Education & employment</h2><p>A little background on their current situation.</p></div></div><div class="form-grid"><label>Educational attainment *<select name="educational_attainment" required><option value="">Select attainment</option><?php foreach (EDUCATION as $option): ?><option <?= $data['educational_attainment'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label>Last school attended<input name="last_school" maxlength="180" value="<?= e($data['last_school']) ?>"></label><label class="span-two">Reason for stopping school<textarea name="reason_stopped" maxlength="1000" rows="3"><?= e($data['reason_stopped']) ?></textarea></label><label>Employment status *<select name="employment_status" required><?php foreach (['Unemployed', 'Employed'] as $option): ?><option <?= $data['employment_status'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label></div></section></div>
<div class="form-side"><section class="panel form-section"><h2>Profile photo</h2><p class="muted">Used on the profile and ID card.</p><div class="photo-preview" id="photo-preview"><?php if (!empty($person['photo'])): ?><?= avatar($person, 'large-avatar') ?><?php else: ?><span class="photo-placeholder"><?= icon('records') ?><small>Add a profile photo</small></span><?php endif; ?></div><label class="file-label">Upload photo<input type="file" name="photo" id="photo-input" accept="image/jpeg,image/png,image/webp"></label><small class="field-help">JPG, PNG or WebP. Maximum 2 MB.<br>Optional; initials appear if no photo is added.</small></section><section class="panel form-section"><h2>Registration details</h2><label>OSY ID<input readonly value="<?= e($person['osy_id'] ?? 'Generated when saved') ?>" tabindex="-1"></label><label>Date registered *<input type="date" name="date_registered" required min="1900-01-01" max="<?= date('Y-m-d') ?>" value="<?= e($data['date_registered']) ?>"></label><label>Record status *<select name="status" required><?php foreach (['Active', 'Inactive'] as $option): ?><option <?= $data['status'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label></section></div><div class="form-actions"><span>Your information is saved securely in your local database.</span><button class="button primary" type="submit"><?= $page === 'edit' ? 'Save changes' : 'Save registration' ?> <?= icon('arrow') ?></button></div></form>
